using System;
class TaiKhoan {
    public double SoDu { get; private set; }
    public void NapTien(double t) {
        if (t > 0) SoDu += t;
    }
}
class Program {
    static void Main() {
        var tk = new TaiKhoan();
        tk.NapTien(500);
        tk.NapTien(300);
        Console.WriteLine(tk.SoDu);
    }
}
